// 反轉鏈結串列（考試高頻題）
public Node<T> Reverse(Node<T> head)
{
    Node<T> prev = null;
    Node<T> curr = head;

    while (curr != null)
    {
        Node<T> next = curr.Next;  // 暫存下一個
        curr.Next = prev;           // 反向指向
        prev = curr;                // prev 前進
        curr = next;                // curr 前進
    }
    return prev;  // prev 即為新的 head
}

// 找鏈結串列中點（快慢指標）
public Node<T> FindMiddle(Node<T> head)
{
    var slow = head;
    var fast = head;
    while (fast != null && fast.Next != null)
    {
        slow = slow.Next;        // 慢指標每次走 1 步
        fast = fast.Next.Next;  // 快指標每次走 2 步
    }
    return slow;  // 快指標到尾時，慢指標在中點
}

