public bool HasCycle(Node<int> head)
{
    var slow = head;
    var fast = head;

    while (fast != null && fast.Next != null)
    {
        slow = slow.Next;        // 慢：每次 1 步
        fast = fast.Next.Next;  // 快：每次 2 步

        if (slow == fast)        // 相遇表示有環
            return true;
    }

    return false;  // fast 到尾，無環
}

