// 括號配對驗證（Stack 經典應用）
public bool IsValidParentheses(string s)
{
    var stack = new Stack<char>();
    foreach (char c in s)
    {
        if (c == '(' || c == '[' || c == '{')
        {
            stack.Push(c);
        }
        else
        {
            if (stack.Count == 0) return false;
            char top = stack.Pop();
            if (c == ')' && top != '(') return false;
            if (c == ']' && top != '[') return false;
            if (c == '}' && top != '{') return false;
        }
    }
    return stack.Count == 0;  // 最後 Stack 必須為空
}

// 用兩個 Stack 實作 Queue
public class QueueViaStacks<T>
{
    private Stack<T> _inbox  = new Stack<T>();
    private Stack<T> _outbox = new Stack<T>();

    public void Enqueue(T item) => _inbox.Push(item);

    public T Dequeue()
    {
        if (_outbox.Count == 0)
            while (_inbox.Count > 0)
                _outbox.Push(_inbox.Pop());  // 倒入 outbox（順序反轉）
        if (_outbox.Count == 0)
            throw new InvalidOperationException("Queue empty");
        return _outbox.Pop();
    }
}

