public string ReverseString(string s)
{
    var stack = new Stack<char>();

    foreach (char c in s)
        stack.Push(c);  // 所有字元推入

    var sb = new System.Text.StringBuilder();
    while (stack.Count > 0)
        sb.Append(stack.Pop());  // LIFO 倒序取出

    return sb.ToString();
}

public class QueueViaStacks<T>
{
    private readonly Stack<T> _inbox  = new Stack<T>();
    private readonly Stack<T> _outbox = new Stack<T>();

    // O(1)
    public void Enqueue(T item) => _inbox.Push(item);

    // Amortized O(1)
    public T Dequeue()
    {
        if (_outbox.Count == 0)
        {
            // 將 inbox 全部倒入 outbox，順序反轉 = FIFO
            while (_inbox.Count > 0)
                _outbox.Push(_inbox.Pop());
        }

        if (_outbox.Count == 0)
            throw new InvalidOperationException("Queue is empty.");

        return _outbox.Pop();
    }

    public int Count => _inbox.Count + _outbox.Count;
}

// Amortized 分析：每個元素最多被 Push 2 次（inbox 一次、outbox 一次）
// 和 Pop 2 次，所以平均每次 Dequeue 是 O(1) amortized。

public List<int> BFS(Dictionary<int, List<int>> graph, int start)
{
    var visited = new HashSet<int>();
    var queue   = new Queue<int>();
    var result  = new List<int>();

    queue.Enqueue(start);
    visited.Add(start);

    while (queue.Count > 0)
    {
        int node = queue.Dequeue();
        result.Add(node);

        if (graph.ContainsKey(node))
        {
            foreach (int neighbor in graph[node])
            {
                if (!visited.Contains(neighbor))
                {
                    visited.Add(neighbor);
                    queue.Enqueue(neighbor);
                }
            }
        }
    }

    return result;
}

