public void BubbleSort(int[] arr)
{
    int n = arr.Length;
    for (int i = 0; i < n - 1; i++)
    {
        bool swapped = false;
        for (int j = 0; j < n - 1 - i; j++)
        {
            if (arr[j] > arr[j + 1])
            {
                int tmp = arr[j];
                arr[j]     = arr[j + 1];
                arr[j + 1] = tmp;
                swapped = true;
            }
        }
        // 一整輪沒有發生交換，表示已完全排序
        if (!swapped) break;
    }
}

public void InsertionSort(int[] arr)
{
    for (int i = 1; i < arr.Length; i++)
    {
        int key = arr[i];  // 當前要插入的元素
        int j   = i - 1;

        // 將比 key 大的元素向右移
        while (j >= 0 && arr[j] > key)
        {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;  // 插入正確位置
    }
}

// 幾乎已排序時效率高的原因：
// while 迴圈幾乎不執行（每個 key 已接近正確位置），
// 內層迭代次數趨近於 0，整體接近 O(n)。

public void MergeSort(int[] arr, int left, int right)
{
    if (left >= right) return;  // 遞迴終止條件

    int mid = left + (right - left) / 2;  // 防止 (left+right) 溢位
    MergeSort(arr, left, mid);
    MergeSort(arr, mid + 1, right);
    Merge(arr, left, mid, right);
}

private void Merge(int[] arr, int left, int mid, int right)
{
    int[] tmp = new int[right - left + 1];
    int i = left, j = mid + 1, k = 0;

    while (i <= mid && j <= right)
    {
        if (arr[i] <= arr[j])  // <= 保證穩定性
            tmp[k++] = arr[i++];
        else
            tmp[k++] = arr[j++];
    }

    while (i <= mid)   tmp[k++] = arr[i++];
    while (j <= right) tmp[k++] = arr[j++];

    Array.Copy(tmp, 0, arr, left, tmp.Length);
}

// 初始：[3, 1, 4, 1, 5]

// Pass 1（i=0）：比較相鄰，最大值 5 浮到末尾
// 3>1 → swap → [1, 3, 4, 1, 5]
// 3<4 → no swap
// 4>1 → swap → [1, 3, 1, 4, 5]
// 4<5 → no swap
// 結果：[1, 3, 1, 4, 5]

// Pass 2（i=1）：次大值 4 到位
// 1<3 → no swap
// 3>1 → swap → [1, 1, 3, 4, 5]
// 3<4 → no swap
// 結果：[1, 1, 3, 4, 5]

// Pass 3（i=2）：swapped=false，提前終止
// 1=1 → no swap
// 1<3 → no swap
// 結果：[1, 1, 3, 4, 5]，swapped=false → break

// 共 3 輪（含提前終止的第 3 輪），排序完成

