public BSTNode Search(BSTNode root, int val)
{
    // 終止條件：null 或找到目標
    if (root == null || root.Value == val)
        return root;

    // BST 性質：比根小往左，比根大往右
    if (val < root.Value)
        return Search(root.Left, val);
    else
