}

public int BinarySearch(int[] arr, int target)
{
    int left = 0, right = arr.Length - 1;

    while (left <= right)
    {
        // 防止 (left + right) 整數溢位
        int mid = left + (right - left) / 2;

        if (arr[mid] == target)
            return mid;
        else if (arr[mid] < target)
            left = mid + 1;   // 目標在右半
        else
            right = mid - 1;  // 目標在左半
    }

    return -1;  // 找不到
}

public List<int> InOrderIterative(BSTNode root)
{
    var result = new List<int>();
    var stack  = new Stack<BSTNode>();
    var curr   = root;

    while (curr != null || stack.Count > 0)
    {
        // 一路往左走，全部推入 Stack
        while (curr != null)
        {
            stack.Push(curr);
            curr = curr.Left;
        }

        // 取出頂端（最左節點）
        curr = stack.Pop();
        result.Add(curr.Value);  // 處理根

        // 轉向右子樹
        curr = curr.Right;
    }

    return result;
}

