// 分析範例：找陣列中兩數之和等於 target

// 方法一：暴力法 O(n²) time, O(1) space
public int[] TwoSum_Brute(int[] nums, int target)
{
    for (int i = 0; i < nums.Length; i++)
        for (int j = i + 1; j < nums.Length; j++)
            if (nums[i] + nums[j] == target)
                return new[] { i, j };
    return null;
}

// 方法二：Hash Table O(n) time, O(n) space
public int[] TwoSum_Hash(int[] nums, int target)
{
    var map = new Dictionary<int, int>();  // value → index
    for (int i = 0; i < nums.Length; i++)
    {
        int complement = target - nums[i];
        if (map.ContainsKey(complement))
            return new[] { map[complement], i };
        map[nums[i]] = i;
    }
    return null;
}
// 用空間換時間：O(n²) → O(n)，空間從 O(1) → O(n)

